using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DodgeEffect", menuName = "Data/Battle/Effects/Austra/Dodge Effect")]
public class DodgeEffect : Effect
{
	private const string thenDecreaseEffectDodgeID = "ThenDecreaseEffectDodge";

	[Header("Decrease Dodge")]
	[SerializeField]
	private int decreaseDodgeAmount;

	[SerializeField]
	private int minimumDodgeAmountOnAustra;

	[Header("Dodge Effects")]
	[SerializeField]
	private ThunderingRiposteEffect thunderingRiposteEffect;

	[SerializeField]
	private DodgeIncreaseOtherEffectsEffect[] dodgeIncreaseOtherEffectsEffects;

	[SerializeField]
	private HurricaneActiveEffect hurricaneActiveEffect;

	[Header("Achievement")]
	[SerializeField]
	private AchievementData cantTouchThisAchievementData;

	public int MinimumDodgeAmountOnAustra => minimumDodgeAmountOnAustra;

	public AchievementData CantTouchThisAchievementData => cantTouchThisAchievementData;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetEffectDescriptionWithAmountReplacedWithX(localizedDescription, GetNumberToReplaceWithX(), DecreaseDodgeDescription());
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), amount, DecreaseDodgeDescription());
	}

	private string DecreaseDodgeDescription()
	{
		if (decreaseDodgeAmount > 0)
		{
			return base.localizationManager.GetLocalizedThenDecreaseEffect(this, decreaseDodgeAmount);
		}
		return base.localizationManager.GetLocalizedString("ThenDecreaseEffectDodge");
	}

	public bool CheckDodge(int chanceAmount, UnitEffects unitEffects, bool normalDodge, int corruptionAmount, GameObject source)
	{
		if (RandomUtilities.RandomChance(chanceAmount))
		{
			if (normalDodge)
			{
				unitEffects.IsEffectActive(this);
			}
			DodgeTriggered(unitEffects, corruptionAmount, normalDodge, source);
			return true;
		}
		return false;
	}

	public void DodgeTriggered(UnitEffects unitEffects, int corruptionAmount, bool normalDodge, GameObject source)
	{
		if (unitEffects.gameObject == ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject)
		{
			if (!cantTouchThisAchievementData.IsUnlocked())
			{
				ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.DodgeInARowAmount++;
				if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.DodgeInARowAmount >= cantTouchThisAchievementData.AchievementVariableAmount)
				{
					cantTouchThisAchievementData.Unlock();
				}
			}
			SpriteControl spriteControl = unitEffects.GetComponent<SpriteControl>();
			if (!unitEffects.GetComponent<CorruptionStats>().IsDefeated())
			{
				spriteControl.PlayAnimationForced(AnimationType.Dodge, AnimationChangeType.ReturnToIdleAnimation);
			}
			else
			{
				spriteControl.PlayAnimationForced(AnimationType.Dodge, AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
				{
					spriteControl.PlayAnimationForced(AnimationType.ReceiveDamage, AnimationChangeType.StayInTheNewAnimationNotLooping);
				});
			}
		}
		SpawnVFX(GetVFXOwnerPosition(unitEffects.gameObject), 2f);
		if (IsVFXEnabled())
		{
			if (unitEffects.gameObject == ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject)
			{
				if (ReferenceSingleton<SFXHandler>.Instance.IsPlayerReceivingCorruptionSFXPlaying())
				{
					PlaySecondEffectActivationSFX();
				}
				else
				{
					PlayEffectActivationSFX();
				}
			}
			else
			{
				PlaySecondEffectActivationSFX();
			}
		}
		if (normalDodge)
		{
			if (unitEffects.gameObject == ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject)
			{
				VacuumWingsOmenData.VacuumWingsValues vacuumWingsValues = ReferenceSingleton<AustraOmensHandler>.Instance.IsVacuumWingsOmenActiveGetVacuumWingsValues();
				int num = corruptionAmount + ((vacuumWingsValues != null) ? (vacuumWingsValues.decreaseDoubleDodgeAmount ? corruptionAmount : vacuumWingsValues.decreaseDodgeAmount) : 0);
				int num2 = minimumDodgeAmountOnAustra;
				if (vacuumWingsValues != null)
				{
					num2 = vacuumWingsValues.minimumDodgeAmount;
				}
				else if (!ReferenceSingleton<AustraOmensHandler>.Instance.ApianLampOmenDataActive)
				{
					num2 = 0;
				}
				int num3 = unitEffects.IsEffectActiveGetAmount(this, activateFeedback: false);
				int num4 = num;
				if (num3 - num < num2)
				{
					num4 = num3 - num2;
				}
				if (num4 > 0)
				{
					unitEffects.IsEffectActiveAndDecreaseEffect(this, num4);
				}
			}
			else
			{
				unitEffects.IsEffectActiveAndDecreaseEffect(this, corruptionAmount);
			}
		}
		unitEffects.IsEffectActiveWithActivation(hurricaneActiveEffect, activateFeedback: false);
		ReferenceSingleton<AustraOmensHandler>.Instance.ActivateOnDodgeOmen(unitEffects.gameObject);
		int num5 = unitEffects.IsEffectActiveGetAmount(thunderingRiposteEffect, activateFeedback: false);
		if (num5 > 0)
		{
			thunderingRiposteEffect.ActivateThunderingRiposte(num5, unitEffects.gameObject, corruptionAmount);
		}
		for (int i = 0; i < dodgeIncreaseOtherEffectsEffects.Length; i++)
		{
			unitEffects.IsEffectActiveWithActivation(dodgeIncreaseOtherEffectsEffects[i], activateFeedback: false);
		}
	}
}
